fn fact(n: i32) -> i32 {
    let mut result = 1;
    for i in 1..=n { result *= i; }
    result
}

fn main() {
    println!("{}", fact(5));
}

fn main() {
    let n = 7;
    let mut a = 0;
    let mut b = 1;
    for i in 0..n {
        print!("{}", a);
        if i < n - 1 { print!(" "); }
        let next = a + b;
        a = b;
        b = next;
    }
    println!();
}

fn main() {
    let n = 17;
    let mut is_prime = n > 1;
    let mut d = 2;
    while d * d <= n {
        if n % d == 0 {
            is_prime = false;
            break;
        }
        d += 1;
    }
    println!("{}", if is_prime { "простое" } else { "составное" });
}

